public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;
    int n = nums.length;
    int total = 0;
    for (int num : nums) total += num;
    // pre-check: for k from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        java.util.Map<String, Boolean> memo = new java.util.HashMap<>();
        if (dfs(nums, 0, k, target, memo)) return true;
    }
    return false;
}

private boolean dfs(int[] nums, int index, int k, int target, java.util.Map<String, Boolean> memo) {
    if (k == 0) return target == 0;
    if (index == nums.length) return false;
    String key = index + "," + k + "," + target;
    Boolean cached = memo.get(key);
    if (cached != null) return cached;
    // Prune
    if (target < 0) { memo.put(key, false); return false; }
    // if not enough numbers left
    if (k > nums.length - index) { memo.put(key, false); return false; }
    // Choose include
    if (dfs(nums, index + 1, k - 1, target - nums[index], memo)) { memo.put(key, true); return true; }
    // Exclude
    if (dfs(nums, index + 1, k, target, memo)) { memo.put(key, true); return true; }
    memo.put(key, false);
    return false;
}

